with open("data/movies.csv", "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f)
    w.writerow(["movie_id", "title", "year", "genres", "director", "cast", "tags"])
    for i, (title, year, genres, director, cast, tags) in enumerate(MOVIES, start=1):
        w.writerow([i, title, year, genres, director, cast, tags])

print(f"wrote {len(MOVIES)} movies to data/movies.csv")
